89	## Common Scopes
90	
91	```kotlin
92	// commonMain/kotlin/coroutines/Scopes.kt
93	// Application scope - lives for app lifetime
94	class ApplicationScope : CoroutineScope {
95	    private val job = SupervisorJob()
96	
97	    override val coroutineContext: CoroutineContext
98	        get() = job + PlatformDispatchers.main +
99	        CoroutineExceptionHandler { _, throwable ->
100	            println("Unhandled exception: $throwable")
101	        }
102	
103	    fun cancel() {
104	        job.cancel()
105	    }
106	}
107	
108	// View scope - tied to a view/presenter lifecycle
109	class ViewScope : CoroutineScope {
110	    private val job = SupervisorJob()
111	
112	    override val coroutineContext: CoroutineContext
113	        get() = job + PlatformDispatchers.main
114	
115	    fun cancel() {
116	        job.cancelChildren()
117	        job.cancel()
118	    }
119	}
120	
121	// Use case scope - for single operations
122	fun useCaseScope(): CoroutineScope =
123	    CoroutineScope(
124	        SupervisorJob() +
125	        PlatformDispatchers.io +
126	        CoroutineExceptionHandler { _, throwable ->
127	            println("Use case failed: $throwable")
128	        }
