207	## Repository Layer Coroutines
208	
209	```kotlin
210	// commonMain/kotlin/data/repository/BaseRepository.kt
211	abstract class BaseRepository {
212	
213	    protected suspend fun <T> execute(
214	        dispatcher: CoroutineDispatcher = PlatformDispatchers.io,
215	        block: suspend () -> T
216	    ): Result<T> = withContext(dispatcher) {
217	        try {
218	            Result.success(block())
219	        } catch (e: CancellationException) {
220	            throw e
221	        } catch (e: Exception) {
222	            Result.failure(e)
223	        }
224	    }
225	
226	    protected suspend fun <T> flowFrom(
227	        dispatcher: CoroutineDispatcher = PlatformDispatchers.io,
228	        block: suspend () -> T
229	    ): Flow<Result<T>> = flow {
230	        emit(withContext(dispatcher) {
231	            try {
232	                Result.success(block())
233	            } catch (e: CancellationException) {
234	                throw e
235	            } catch (e: Exception) {
236	                Result.failure(e)
237	            }
238	        })
239	    }
240	
241	    // For single-shot database operations
242	    protected suspend fun <T> databaseQuery(
243	        block: suspend () -> T
244	    ): T = withContext(PlatformDispatchers.io) {
245	        block()
246	    }
247	
248	    // For network operations with timeout
249	    protected suspend fun <T> networkCall(
250	        timeout: Duration = 30.seconds,
251	        block: suspend () -> T
252	    ): T = withTimeout(timeout) {
253	        withContext(PlatformDispatchers.io) {
254	            block()
255	        }
256	    }
257	}
258	
259	// Usage
260	class UserRepository(
261	    private val localDataSource: UserLocalDataSource,
262	    private val remoteDataSource: UserRemoteDataSource
263	) : BaseRepository() {
264	
265	    suspend fun getUser(id: String): Result<User> = execute {
266	        remoteDataSource.getUser(id).also { user ->
267	            localDataSource.saveUser(user)
268	        }
269	    }
270	
271	    fun observeUser(id: String): Flow<Result<User>> = flowFrom {
272	        localDataSource.getUser(id) ?: remoteDataSource.getUser(id).also {
273	            localDataSource.saveUser(it)
274	        }
275	    }
276	}
277	```
