279	## Use Case Patterns
280	
281	```kotlin
282	// commonMain/kotlin/domain/base/BaseUseCase.kt
283	abstract class BaseUseCase<in P, R> {
284	    suspend operator fun invoke(parameters: P): Result<R> {
285	        return try {
286	            execute(parameters).let { Result.success(it) }
287	        } catch (e: CancellationException) {
288	            throw e
289	        } catch (e: Exception) {
290	            Result.failure(e)
291	        }
292	    }
293	
294	    protected abstract suspend fun execute(parameters: P): R
295	}
296	
297	// No parameters
298	abstract class BaseNoParamsUseCase<R> {
299	    suspend operator fun invoke(): Result<R> {
300	        return try {
301	            execute().let { Result.success(it) }
302	        } catch (e: CancellationException) {
303	            throw e
304	        } catch (e: Exception) {
305	            Result.failure(e)
306	        }
307	    }
308	
309	    protected abstract suspend fun execute(): R
310	}
311	
312	// Flow use case
313	abstract class FlowUseCase<in P, R> {
314	    operator fun invoke(parameters: P): Flow<Result<R>> = flow {
315	        try {
316	            emit(Result.success(execute(parameters)))
317	        } catch (e: CancellationException) {
318	            throw e
319	        } catch (e: Exception) {
320	            emit(Result.failure(e))
321	        }
322	    }
323	
324	    protected abstract suspend fun execute(parameters: P): R
325	}
326	
327	// Usage
328	class GetUsersUseCase(
329	    private val repository: UserRepository
330	) : BaseNoParamsUseCase<List<User>>() {
331	    override suspend fun execute(): List<User> {
332	        return repository.getAllUsers()
333	    }
334	}
335	
336	class ObserveUserUseCase(
337	    private val repository: UserRepository
338	) : FlowUseCase<String, User>() {
339	    override suspend fun execute(parameters: String): User {
340	        return repository.getUser(parameters)
341	    }
342	
343	    fun flow(id: String): Flow<Result<User>> {
344	        return repository.observeUser(id)
345	    }
346	}
347	```
