349	## Worker for Background Tasks
350	
351	```kotlin
352	// commonMain/kotlin/coroutines/BackgroundWorker.kt
353	class BackgroundWorker(
354	    private val scope: CoroutineScope
355	) {
356	    private val workers = mutableMapOf<String, Job>()
357	
358	    fun start(
359	        key: String,
360	        interval: Duration,
361	        dispatcher: CoroutineDispatcher = PlatformDispatchers.io,
362	        work: suspend () -> Unit
363	    ) {
364	        workers[key]?.cancel()
365	        workers[key] = scope.launch(dispatcher) {
366	            while (isActive) {
367	                try {
368	                    work()
369	                } catch (e: Exception) {
370	                    println("Worker $key failed: $e")
371	                }
372	                delay(interval)
373	            }
374	        }
375	    }
376	
377	    fun stop(key: String) {
378	        workers[key]?.cancel()
379	        workers.remove(key)
380	    }
381	
382	    fun stopAll() {
383	        workers.values.forEach { it.cancel() }
384	        workers.clear()
385	    }
386	}
387	```
